def check_k(n, k):
    for m in range(2, n + 1):
        q = n // m
        r = n % m
        e_p = (n**2 - (m * q**2 + 2 * r * q + r)) // 2
        if e_p < k * (m - 1):
            return False, m, e_p, k * (m - 1)
    return True, None, None, None

